const fs=require('node:fs'),path=require('node:path');
const here=__dirname;
const records=JSON.parse(fs.readFileSync(path.join(here,'records-base.json'),'utf8'));
const get=key=>{const r=records.find(r=>r._key===key);if(!r)throw Error(key);return r};
function set(key,answer,explanation,example='',points=[],issues=[]){const r=get(key);Object.assign(r,{directAnswer:answer,explanation,example,importantPoints:points,issues:[...r.issues,...issues]});}
const algorithms = [
 ['Carry the previous two Fibonacci numbers iteratively.','Define F(0)=0 and F(1)=1; reject negative or noninteger inputs. This uses O(n) arithmetic steps and O(1) live integer references, avoiding exponential recursive recomputation. Actual bit complexity and integer storage grow with n.','p fibonacci(10) # 55','A memoized recursive solution still uses O(n) stack depth; iteration avoids that stack.'],
 ['Use Floyd’s slow/fast pointer algorithm to detect a cycle in O(n) time and O(1) extra space.','Advance one pointer by one node and another by two. If they are identical a cycle exists; if the fast pointer reaches nil the list is acyclic. Compare node identity, not potentially overloaded value equality.','p cyclic?(head)','The input nodes must provide a next link; a nil head has no cycle.'],
 ['Use dynamic programming, processing denominations outside amounts to count unordered combinations.','Start ways[0]=1. For each unique positive coin, add ways[amount-coin] into ways[amount] for increasing amounts. Coin-first iteration avoids counting the same combination in different orders. Complexity is O(amount × denomination_count) time and O(amount) space.','p change_ways(4, [1, 2, 3]) # 4','Zero and negative denominations are invalid; duplicate denominations must not multiply counts.'],
 ['Use an incoming stack for pushes and an outgoing stack for removals, transferring only when outgoing is empty.','Each element moves between the stacks at most once before removal. Individual transfers can take O(n), but each queue operation is amortized O(1). An empty dequeue should have an explicitly defined result or exception.','queue = TwoStackQueue.new\nqueue.push(1).push(2)\np queue.shift # 1','Amortized constant time is not a worst-case latency guarantee.'],
 ['Intersect the rectangles independently on the x and y axes and multiply the nonnegative overlap lengths.','Use max(left edges) and min(right edges), likewise for top/bottom. Clamp negative overlap to zero. This assumes axis-aligned rectangles and nonnegative width/height; rotated rectangles need polygon geometry. Complexity is O(1).','p overlap_area({x:0,y:0,width:3,height:3}, {x:2,y:1,width:3,height:3}) # 2','Touching edges yield zero area; decide whether an API should also return the overlap rectangle.'],
 ['Maintain min, max, count, sum and frequency counts as temperatures arrive.','Each insertion updates min/max, sum/count for mean, and a histogram for mode. Operations are expected O(1), with O(k) memory for k distinct temperatures; a fixed bounded integer range gives fixed-size storage. Define tie handling and empty queries.','tracker = TemperatureTracker.new\n[10, 20, 20].each { |t| tracker.insert(t) }\np [tracker.min, tracker.max, tracker.mean, tracker.mode] # [10, 20, 16.666..., 20]','Use a numerically stable running mean if accumulating large floating-point values; a mode may have ties.'],
 ['Under the stated standard variant, compare the minimum and maximum depths of all leaves and require a difference of at most one.','The source does not define its invented term “superbalanced”; this answer explicitly assumes the usual leaf-depth definition. A DFS tracks leaf depths and exits as soon as the difference exceeds one. O(n) time and O(h) traversal stack for tree height h; it is not the same condition as local AVL height balance.','p superbalanced?(root)','The actual interviewer must define the custom property before implementation.'],
 ['Traverse the tree with inherited lower and upper bounds, not just comparisons against immediate children.','A left descendant must remain below every relevant ancestor bound, and a right descendant above it. The example assumes strict ordering with no duplicate keys. O(n) time and O(h) traversal stack on a tree of height h.','p valid_bst?(root)','Checking only each node against its children misses violations deeper in a subtree.'],
 ['Walk to the rightmost node; the second largest is its parent unless that node has a left subtree, whose largest value is the answer.','The method assumes a valid strict BST containing at least two nodes. It follows the right spine and, when necessary, the maximum of the largest node’s left subtree. Time is O(h), constant auxiliary space.','p second_largest(root)','Distinct-value versus node-order semantics must be clarified when duplicate keys are permitted.'],
 ['Choose a structure according to the query: a hash set for exact membership or a trie for prefix operations and shared-prefix storage.','The source only names a search engine without full requirements. A trie stores one edge per character, marks word endings, and supports O(L) lookup for a word of L characters. For full-text ranked search, an inverted index, tokenization, document IDs and ranking are additional requirements. Trie overhead can exceed a hash set despite prefix sharing.','trie = {}\ntrie_insert(trie, "ruby")\np trie_include?(trie, "ruby") # true\np trie_include?(trie, "rub") # false','This is an explicitly scoped membership example, not a complete search-engine architecture.'],
 ['Use binary search on a sorted array, halving the candidate interval each step.','Compare the midpoint with the target, discard the impossible half and stop when found or the interval is empty. O(log n) comparisons and O(1) space assume random indexed access and a sorted collection under the same comparison rule.','p binary_include?([1, 3, 5, 7], 5) # true','A linked list does not give constant-time midpoint access.'],
 ['Binary-search for the smallest element by comparing a midpoint with the right endpoint.','Distinct sorted values permit O(log n) time. Duplicates can make halves indistinguishable and degrade worst-case runtime to O(n). Return nil for an empty array; the shown variant returns an index of a minimum.','p rotation_index([4, 5, 6, 1, 2, 3]) # 3','When duplicate minima straddle the rotation, define whether any minimum index or a specific boundary is wanted.'],
 ['Scan movie lengths with a hash set of prior lengths, testing the complementary duration before inserting the current one.','Checking before insertion ensures the same movie instance is not reused. Two distinct movies of equal duration are allowed when two entries exist. Expected O(n) time and O(n) memory.','p movie_pair?([60, 90, 120], 180) # true','Clarify whether durations must match exactly and whether trailers or buffers count.'],
 ['Use unbounded-knapsack dynamic programming over bag capacity.','For each capacity, try every positive-weight cake whose weight fits and reuse the best smaller-capacity value. O(capacity × cake_types) time and O(capacity) space. A zero-weight positive-value cake makes the optimum unbounded; zero-weight nonpositive cakes can be ignored.','p cake_value([[3, 40], [5, 70]], 10) # 140','Greedy value-per-weight is not generally correct for indivisible cakes.'],
 ['Store values on one stack and current maxima on a second stack.','Push a maximum when the new value is at least the prior maximum, and pop the maximum when removing that same value. Using >= preserves repeated maxima. Push, pop and get_max are O(1); extra memory is O(n).','stack = MaxStack.new\nstack.push(3).push(7).push(7)\nstack.pop\np stack.max # 7','Define whether max on an empty stack returns nil or raises.'],
 ['XOR all integer IDs; pairs cancel and leave the ID that occurs once.','This relies on every other ID appearing exactly twice and the special ID exactly once. XOR is associative, commutative and x ^ x = 0. O(n) operations and constant extra machine-word storage for bounded IDs; arbitrary-width integer arithmetic has its own bit costs.','p unique_id([4, 2, 4, 7, 2]) # 7','This does not solve arbitrary frequency anomalies without additional assumptions.'],
 ['With only a non-tail node, copy its successor’s value and bypass the successor.','This changes the logical contents of the supplied node rather than physically deleting that exact object. A tail cannot be removed this way because its predecessor is unavailable. O(1) pointer work assumes values can be copied cheaply.','delete_non_tail(node)','External references and node identity may make this technique inappropriate.'],
 ['Reverse each next pointer while tracking previous, current and following nodes.','Save the original following node before overwriting current.next, then advance. Return the last visited node as the new head. O(n) time and O(1) auxiliary references for an acyclic singly linked list.','head = reverse_list(head)','A cycle needs separate handling; traversal otherwise does not terminate.'],
 ['Keep two pointers k nodes apart and advance them together until the leading pointer reaches the end.','For k=1 the trailing pointer ends at the last node. Reject k<=0 and k larger than the list length. O(n) time and O(1) extra space without first counting the list.','p kth_last(head, 1).value','Clarify one-based versus zero-based indexing.'],
 ['For an ASCII mutable String, swap bytes from the two ends toward the center.','The standard O(n)-time, O(1)-extra-space two-pointer solution is straightforward for bytes or a mutable character array. UTF-8 code points and grapheme clusters use variable byte lengths, so byte reversal corrupts general text. The supplied code deliberately rejects non-ASCII rather than making a false Unicode guarantee.','text = +"ruby"\nreverse_ascii!(text)\np text # "ybur"','For user-visible Unicode, define the unit (code point or grapheme) and accept or design for additional storage.'],
 ['For the ASCII space-delimited variant, reverse the whole string, then reverse each word region.','The first reversal flips word order and letters; reversing each nonspace region restores letter order. O(n) time and O(1) auxiliary space for a mutable ASCII String. Runs of spaces are retained but their positions follow the global reversal. A split/reverse/join solution is simpler when in-place memory is not required.','text = +"cake thief"\nreverse_words_ascii!(text)\np text # "thief cake"','Clarify whitespace, punctuation and Unicode before promising exact formatting.'],
 ['Starting at the opening parenthesis, track nesting depth and return the first index where it falls back to zero.','Increment for ( and decrement for ); ignore other characters in this standard text variant. Reject an invalid opening index or unmatched open. O(n) scan time and O(1) extra state. Parsing a programming language with quoted strings/comments requires additional lexical rules.','p closing_parenthesis("a(b(c)d)e", 1) # 7','The input index must refer to an opening parenthesis.'],
 ['Use a stack of opening brackets and require each closing bracket to match the latest opener.','Push (, [ and {. For a closer, fail if the stack is empty or its top is not the matching opener. Accept only if the stack is empty at the end. O(n) time and O(n) worst-case stack space. The code ignores non-bracket characters by explicit policy.','p valid_brackets?("{a:[()]}") # true\np valid_brackets?("([)]") # false','A counter alone cannot check mixed bracket nesting.'],
 ['A string has a palindromic permutation exactly when at most one character has an odd count.','Toggle each character in a set or count frequencies. Two copies occupy mirrored positions; at most one odd-count character can occupy the center. O(n) time and O(k) space for k distinct characters, or fixed space for a fixed alphabet.','p palindrome_permutation?("civic") # true','Decide whether case, spaces, punctuation and Unicode normalization matter.'],
 ['Recursively choose each distinct leading character and permute the remaining characters.','The base case for the empty string returns one empty permutation. Using distinct choices at each depth avoids duplicate outputs for repeated characters. The output can contain n! strings, so factorial time and output space are unavoidable when all permutations are materialized.','p permutations("aba").sort # ["aab", "aba", "baa"]','A lazy generator can reduce retained output memory, not the number of results.'],
 ['Use counting sort when each score is an integer in a known bounded range.','Count each score, then emit the required number in order. O(n + maximum_score) time and O(maximum_score) count memory plus output. It is inefficient when the score range is huge relative to the input.','p sort_scores([30, 10, 30, 20], 100) # [30, 30, 20, 10]','Choose ascending or descending explicitly and reject out-of-range scores.'],
 ['For the standard 1..n plus one-extra variant, subtract the expected arithmetic-series sum from the actual sum.','The source does not state the domain or repetition count. This O(n)-time, O(1)-extra-state method is valid only when each 1..n occurs once and exactly one value occurs one additional time. A hash set works for a less constrained duplicate search at O(n) memory.','p one_duplicate_sum([1, 2, 3, 2]) # 2','Multiple duplicated/missing values invalidate the arithmetic trick.'],
 ['Tokenize under an explicit word policy and count tokens with a Hash.','The example lowercases and preserves internal apostrophes while splitting on other nonword boundaries. O(total text length) scanning plus O(k) distinct-token storage is typical. Production Unicode tokenization may need normalization and language-specific segmentation.','p word_counts("Ruby, ruby! It’s useful.") # {"ruby"=>2, "it’s"=>1, "useful"=>1}','A plain split treats punctuation as part of words; choose the required behavior.'],
 ['Use Fisher–Yates: for each index from the end downward, swap with a uniformly selected index from zero through that index.','This yields every permutation with probability 1/n! when the RNG is uniform. O(n) swaps and O(1) extra storage. Shuffling by sorting random keys or repeatedly selecting any full-array index does not give the same guarantees.','p shuffle!([1, 2, 3, 4], Random.new(123))','Use a cryptographically appropriate random source when unpredictability is a security requirement.'],
 ['Walk the served sequence while advancing the head pointer of whichever source queue matches each order.','With globally unique order IDs, each served order must match the next unserved takeout or dine-in order. Reject length mismatches and leftovers. O(n) time and O(1) auxiliary state. If IDs can repeat across streams, the greedy choice can become ambiguous and needs stronger identity or a different algorithm.','p first_come_first_served?([1, 3], [2, 4], [1, 2, 3, 4]) # true','The merged sequence may interleave streams but must preserve each stream’s internal order.'],
 ['Roll the fair seven-sided die until a result in 1..5 appears, then return it.','Rejection sampling removes outcomes 6 and 7. Each accepted value has equal probability; the expected number of rolls is 7/5. Runtime has no finite worst-case roll bound, though termination occurs with probability one for independent fair rolls.','p five_from_seven(-> { rand(1..7) })','Taking die7 % 5 biases some outcomes.'],
 ['Use two fair five-sided rolls to generate 0..24, reject 21..24 and map 0..20 modulo seven.','The 25 pairs are equally likely. Accepting 21 of them gives exactly three pairs per seven-sided result. Expected die rolls are 2 × 25/21 = 50/21, with unbounded worst-case retries.','p seven_from_five(-> { rand(1..5) })','A modulo operation is unbiased only after the input range is a multiple of seven.'],
 ['With two eggs and 100 floors, 14 drops suffice in the worst case.','Choose the smallest k satisfying k(k+1)/2 >= 100. Drop the first egg after gaps k, k-1, k-2 and so on; if it breaks, linearly test the previous gap with the second egg. The shrinking gap balances worst-case total drops. This assumes a monotonic break threshold, identical eggs, and that broken eggs cannot be reused.','p two_egg_worst_case(100) # 14','If the interview permits more eggs or different floor counts, the optimal recurrence changes.'],
 ['Under the bounded-domain variant, binary-search the value range and count how many values fall in each half.','For n+1 values in 1..n, the pigeonhole principle guarantees a duplicate. If at most mid values can fit in the lower range but more than mid appear there, that range contains a duplicate. O(n log n) time and O(1) extra state, without modifying the input.','p duplicate_low_space([1, 3, 4, 2, 2]) # 2','The source omits these essential bounds; this is a labelled standard variant.'],
 ['Interpret the bounded-domain array as pointers and use Floyd’s cycle detection to find the duplicate entry value.','For n+1 elements containing values in 1..n, following indices eventually enters a cycle. One phase finds a meeting point; restarting one pointer at the path’s beginning and moving both one step finds the cycle entrance. O(n) time, O(1) space and no mutation under the stated standard assumptions.','p duplicate_floyd([1, 3, 4, 2, 2]) # 2','This is not a solution to an arbitrary unconstrained array duplicate problem.'],
 ['Group files by size, then hash only equal-sized candidates, then confirm byte equality before any removal decision.','Size filtering avoids hashing most unique files. Streaming hashes bound buffer memory; equal hashes are candidates, not a mathematical proof of equality. Define whether symlinks, hard links, names, modification times and concurrent writes matter. The example only detects candidates; it never deletes files or decides which is the original.','p duplicate_file_candidates(["a.txt", "b.txt"])','Treat disappearing/unreadable/changing files explicitly; user-selected retention is required for actual deletion.'],
 ['Scan prices once, tracking the minimum earlier price and the best sale profit seen so far.','Compute a candidate sale before updating the minimum so buying and selling at the same timestamp is not used. O(n) time and O(1) extra numeric state. If one trade is mandatory, a falling series yields a negative result; if no trade is allowed, clamp the answer to zero as a separate policy.','p maximum_stock_profit([10, 7, 5, 8, 11, 9]) # 6','At least two time-ordered prices are required.'],
 ['Multiply prefix products into an output array, then multiply suffix products in a reverse pass.','For each index the prefix omits that element and everything to its right; the suffix omits that element and everything to its left. O(n) arithmetic operations, O(n) output space and O(1) extra state. Zeros and negative values work without division or special-case arithmetic.','p products_except_self([1, 2, 3, 4]) # [24, 12, 8, 6]','Clarify what an empty input and a single-element input should mean; this variant returns [] and [1].'],
 ['Track the three largest numbers and the two smallest numbers, then compare the relevant products.','The maximum is either the product of the three largest or the largest times the two most negative. Maintaining fixed-size candidate arrays keeps O(n) time and O(1) extra space; sorting the entire input would cost O(n log n). Require at least three numbers.','p highest_product_three([-10, -10, 1, 3, 2]) # 300','Choosing only the largest positive numbers fails when two negatives produce a larger positive product.'],
 ['Sort intervals by start time, then sweep and extend the current merged interval while overlaps continue.','O(n log n) sorting dominates; scanning is O(n). The example merges touching intervals as well as overlapping ones and preserves the original input ranges by writing new output pairs. Decide whether meetings are half-open and whether adjacent meetings should merge.','p merge_meetings([[0, 1], [3, 5], [4, 8], [8, 9]]) # [[0, 1], [3, 9]]','Validate start <= end and define zero-length meeting behavior.'],
 ['Model events, performances, seats, inventory holds, orders and payments; enforce seat ownership atomically in the database.','Scope requirements first: reserved seats versus general admission, purchase limits, resale, payment-provider behavior and peak sale traffic. For reserved seats use a unique inventory identity such as (performance_id, seat_id), transactional conditional updates or row locks, expiring holds, and an order state machine. Use idempotency keys for checkout and payment callbacks. A durable outbox/job processes follow-up work after commit; signed webhooks reconcile external payment state without pretending the database and provider share one transaction. Rate limits, a waiting room, caching of read-only event data and load shedding protect scarce inventory. Measure hold contention, queue lag, payment failure and reconciliation, and test simultaneous attempts for the final seat.','Inventory.transaction do\n  seat = Inventory.lock.find_by!(performance_id: performance.id, seat_id: seat_id)\n  raise SoldOut unless seat.available?\n  seat.update!(status: "held", hold_token: token, held_until: 5.minutes.from_now)\nend\n# Schematic Rails code; add a real state machine, constraints and payment workflow.','Do not hold a database transaction open while calling a payment API; use durable states and reconciliation.']
];
const ruby=fs.readFileSync(path.join(here,'algorithms.rb'),'utf8');
for(let i=0;i<algorithms.length;i++){
 const n=i+1,[answer,explain,example,point]=algorithms[i],r=get('fourteen:'+n);
 const start=ruby.search(new RegExp('^# '+n+'\\.','m'));
 const next=n<41?ruby.search(new RegExp('^# '+(n+1)+'\\.','m')):ruby.length;
 const solution=start>=0?ruby.slice(start,next>=0?next:ruby.length).trim():'';
 Object.assign(r,{category:n===41?'E':'D',difficulty: n<5||[11,13,16,20,24,28,37,38].includes(n)?'Intermediate':'Advanced',directAnswer:answer,explanation:explain,example:solution+'\n\n# Example usage:\n'+example,importantPoints:[point,'The original file supplies a catalog prompt, not a complete worked answer. This solution is newly authored.'],issues:['Incomplete source: linked solution and detailed constraints are not included; assumptions are explicitly stated in this answer.']});
}
const mcq={
 'unless-1':['a) True.','unless condition; body; else; other; end is a valid ordinary unless form. The bracketed [then] denotes an optional keyword, not literal brackets in Ruby code.'],
 'unless-2':['a) It prints x is greater than 2.','x>2 is true, so the unless body is skipped and else runs. The label is descriptive text, not an assertion that all values failing the first branch are strictly greater.'],
 'unless-3':['d) It prints lines 1 and 3.','The integer 1 is truthy, so the first if executes and the following unless does not. After var=false, the last unless executes.'],
 'unless-4':['a) It prints Not hungry.','hungry is false, so unless hungry executes its first branch.'],
 'unless-5':['a) True.','Ruby supports the modifier form expression unless condition; it executes expression only for a falsy condition.'],
 'unless-6':['b) It prints 14.','12 is truthy, so the else branch computes counter+2. Ruby does not treat zero or other integers as falsy.'],
 'unless-7':['It prints the lowercase String false (option b is closest).','true && false evaluates to false, so unless executes print "false". The output is a String and print returns nil. The option capitalizes False, which is not the exact output.'],
 'unless-8':['b) It prints 2 is less than 3.','2>3 is false, so the modifier unless allows the print call.'],
 'unless-9':['c) It prints both x is less than y and x is less than y+1 on separate lines.','Both 8>10 and 8>11 are false, so both unless bodies run.'],
 'unless-10':['b) It prints 4, 8 and length of x is less than that of y.','"ruby" has length four; "language" has length eight. puts x,y writes separate lines, and unless 4>8 executes the print.'],
 'unless-11':['b) It prints only x is less than y+1.','8<10 is true, so the first unless body is skipped. 8>11 is false, so the second body runs.'],
 'case-1':['c) It prints little child.','The range 3..6 matches age=5 using Range#===. Earlier 0..2 does not match.'],
 'case-2':['a) True as pseudocode for the ordinary case syntax.','Each when can list multiple comma-separated patterns and optional then. Ellipses are placeholders, not literal Ruby tokens in the shown template.'],
 'case-3':['d) SyntaxError.','In a case target expression, branch labels must begin with when. The source puts calls before when and places else after an expression.'],
 'case-4':['c) It prints 1/baby, 2/baby, then 3/4/5 each followed by little child, on separate lines.','The for loop visits 1 through 5. The first two match 0..2 and the last three match 3..6.'],
 'case-5':['The output depends on the missing standard input.','The when expressions assign strings "a", "b" and "c", and their resulting String values are compared with the original case target. Input a prints alphabet a; b prints alphabet b; c prints alphabet c; otherwise it prints some other alphabet. The assignments are legal but confusing; write when "a" instead.'],
 'case-6':['a) True.','A target case tests when_expression === target in order and runs else only if none match.'],
 'case-7':['The exact output needs the input; input ruby produces length is 4, matching the scenario in option a.','The target length.length is evaluated before any when assignments. A four-character input matches the integer 4 assigned in the first when; a five-character input matches 5. These assignments overwrite the local variable but do not change the already evaluated target.'],
 'case-8':['The exact output needs the input; input ruby produces length is 4, matching option a’s scenario.','String reversal preserves its character count, so the same length cases apply. The source never supplies a definite input, and the variable assignments are legal but misleading.'],
 'case-9':['c) SyntaxError.','The print-before-when arrangement is invalid syntax for this case statement. The correct structure is when 9 then print "ruby".'],
 'case-10':['a) True.','The direction is when_pattern === case_target. This is why a Range, Regexp or Class can act as a case pattern.'],
 'comparison-1':['a) True under the broad “relational/comparison operator” terminology used by the source.','== calls the receiver’s equality operation. Some references distinguish equality operators from ordering operators; the terminology does not alter its Ruby behavior.'],
 'comparison-2':['a) True.','= assigns a value; it does not test equality. Use == for an ordinary value-equality comparison.'],
 'comparison-3':['a) true.','9 != 10 evaluates to true, and that Boolean is assigned to a.'],
 'comparison-4':['b) true, true, true, false, each printed on a new line.','17>16, 21<=30 and 9>=9 are true; -11>4 is false. Ruby’s Boolean spellings are lowercase.'],
 'comparison-5':['b) It prints Not same.','"string" and "strings" have different String values, so == returns false.'],
 'comparison-6':['b) False.','Assignment and comparison are different operations. Ruby assignment expressions also return the assigned value.'],
 'comparison-7':['a) It prints a greater than b.','The integers are 10 and 9, so the greater-than comparison is true.'],
 'comparison-8':['d) All of the mentioned.','Equality, inequality and ordering relations are comparisons; whether an object supports an ordering operation depends on its class.'],
 'comparison-9':['c) Error when run as the standalone supplied snippet: a is undefined.','b=9 is assignment, not comparison, and yields the truthy integer 9. If a were initialized to 10, the condition would succeed and assign b. With no earlier definition of a in this snippet, it raises NameError. The intended complete context is missing.'],
 'comparison-10':['a) SyntaxError.','The if statement lacks its terminating end. With end supplied, the shown statements print 1 and change counter to 2; there is no loop to print 2.'],
 'operator-1':['a) True in the source’s terminology.','Logical operators combine or negate truthiness; Ruby’s && and || return selected operand values rather than necessarily Booleans.'],
 'operator-2':['d) All of the mentioned.','Ruby supports &&/and, ||/or and !/not, but each pair has different precedence, so the spellings are not blindly interchangeable.'],
 'operator-3':['a) True for inputs restricted to the Boolean objects true and false; the unrestricted Ruby claim needs qualification.','&& returns its first falsy operand or its last evaluated operand. For example 1 && 2 returns 2, not true. It expresses logical conjunction of truthiness without converting results into Booleans.'],
 'operator-4':['b) false.','The first operand is truthy, so the second operand false is evaluated and returned.'],
 'operator-5':['b) false.','77<78 is true, but 77<77 is false; the conjunction returns false.'],
 'operator-6':['a) true.','The left operand is already true, so || returns it and skips evaluation of the right operand.'],
 'operator-7':['b) false.','true&&false is false and !true is false; false||false is false.'],
 'operator-8':['b) false.','!true is false; && short-circuits immediately.'],
 'operator-9':['a) true.','3<4||false is true; false||true is true; their conjunction is true.'],
 'operator-10':['b) false.','The negation of the truthy left OR expression is false, so the conjunction is false.'],
 'operator-11':['a) true.','2**3 is 8 and 3**2 is 9; inequality is true. The trailing ||true also guarantees a truthy Boolean result here.'],
 'operator-12':['b) false.','-10>-9 is false, so false||false returns false.'],
 'operator-13':['b) false.','700/10 is the integer 70; equality is true and negation makes it false.'],
 'operator-14':['b) false and false, on separate lines.','Both !true and !true&&!true evaluate to false.'],
 'operator-15':['b) false.','The leading !true is false, so && short-circuits without needing the right-hand expression.']
};
for(const [key,[answer,explanation]]of Object.entries(mcq)){
 const r=get('twentyone:'+key);
 let code=r.sourceAnswer.split('\n');let opt=code.findIndex(l=>/^a\)/.test(l));if(opt>=0)code=code.slice(0,opt);
 code=code.filter(l=>!/^\s*(?:Sanfoundry|This set|his set|To practice|👉|🎓|←)/.test(l));
 Object.assign(r,{directAnswer:answer,explanation,example:code.join('\n').trim(),importantPoints:['All original answer options are retained in sourceAnswer.','This answer is independently derived; the source only says “View Answer” and includes no visible key.','Reference: https://docs.ruby-lang.org/en/3.4/syntax/control_expressions_rdoc.html'],issues:[...r.issues,'Incomplete source: hidden answer key/rationale was not captured; a derived answer is supplied.']});
 if(['case-5','case-7','case-8','comparison-9'].includes(key))r.issues.push('Incomplete source: input or prior variable initialization is not supplied; conditional outcomes are stated instead of inventing it.');
}
