for(const a of audit){
 const own=records.filter(r=>r.sourceFile===a.sourceFile);
 a.extractedCount=own.length;a.recordRanges=own.map(r=>[r.startLine,r.endLine]);
 const covered=Array(a.totalLines).fill(false);
 for(const r of own)for(let line=r.startLine;line<=r.endLine;line++)covered[line-1]=true;
 const omitted=[];for(let i=0;i<covered.length;){if(covered[i]){i++;continue;}const start=i++;while(i<covered.length&&!covered[i])i++;omitted.push({startLine:start+1,endLine:i,disposition:'Publisher metadata, introduction/duplicate table of contents, section framing, promotion, related-link or footer material; original text retained in the unchanged source file. Technical concepts appearing here are covered by the extracted concept/question records.'});}
 a.omittedRanges=omitted;a.corrections=own.flatMap(r=>r.issues.filter(s=>!/Incomplete source/.test(s)).map(issue=>({key:r._key,startLine:r.startLine,issue})));
 a.repeatedContentsMappings=[];
 const originalLines=fs.readFileSync(path.resolve(here,'../../../ruby',a.sourceFile),'utf8').split(/\r?\n/);
 for(let line=0;line<originalLines.length;line++){
  if(covered[line])continue;
  const match=originalLines[line].match(/^(\d+)\. (.+)$/);
  if(match){const same=own.find(r=>r.question.trim()===match[2].trim());if(same)a.repeatedContentsMappings.push({sourceLine:line+1,question:match[2],disposition:'Repeated table-of-contents entry, not a separate answer occurrence',mapsToKey:same._key,answerStartLine:same.startLine});}
 }
 a.incompleteSourcePrompts=own.filter(r=>r.issues.some(s=>/Incomplete source/i.test(s))).map(r=>({key:r._key,startLine:r.startLine,issues:r.issues.filter(s=>/Incomplete source/i.test(s))}));
 if(a.sourceFile==='twentyfour.txt')a.notes.push('Headline advertises 100 questions, but only 15 question bodies are present. No absent questions were invented.');
 if(a.sourceFile==='fourteen.txt')a.notes.push('41 catalog prompts preserved; all supplied solutions are original standard variants with explicit assumptions, not recovered linked content.');
 if(a.sourceFile==='twentyone.txt')a.notes.push('46 MCQs; answer keys were not captured. Derived solutions are explicitly labelled and all original options remain in sourceAnswer.');
 if(a.sourceFile==='nine.txt')a.notes.push('Lines 835–853 are related-post teasers about Ruby and Rails already covered by the extracted Ruby/Rails definition records, not additional complete interview questions.');
 if(a.sourceFile==='thirteen.txt')a.notes.push('Lines 1–15 frame Ruby interview-language choice and contain dated 2022/2023 usage/salary statistics. These remain as raw source context; runtime distinctions are extracted at line 16. No current statistical claim is inferred.');
}
